#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [0.031156475, 0.21750401, 0.0033961750000000013], 'basis': [[-0.0, 0.9810520206195451, 0.19374450402090831], [0.07483551783138168, -0.19320122333714965, 0.978301043938898], [0.9971958911221551, 0.014498970285388884, -0.07341753598258699]], 'axis': [0.19374450402090831, 0.978301043938898, -0.07341753598258699], 'zmin': -0.10892133377499125, 'zmax': 0.11026479571083116, 'profiles': [{'outer': [[-0.027970460202875833, -0.01598140569690968], [-0.027173221081976152, -0.013615034102043554], [-0.026365456376464362, -0.011614182018793393], [-0.0251262026017187, -0.008768774755202593], [-0.023561613361962632, -0.005310561465437338], [-0.021864287503548088, -0.0016841872434651868], [-0.019928671270583072, 0.0021855482646302568], [-0.01805189035601677, 0.0056226874844750654], [-0.01619645712931875, 0.008645807875549366], [-0.014285484263617174, 0.01133875179158536], [-0.012293672007347062, 0.013782039221874154], [-0.01014411333306034, 0.016046576904387263], [-0.007830585725929064, 0.018021038642499286], [-0.005384297463322983, 0.019549688467868732], [-0.004378119033558733, 0.020088177716306607], [-0.0016745303081682648, 0.020970897875710066], [-0.000731148209519983, 0.021124758059475415], [0.002134772214116335, 0.021135062021818342], [0.005101233763000622, 0.020404072732007457], [0.008160034279516712, 0.019074032397579606], [0.011278635754283534, 0.01726880728084557], [0.014460996724522382, 0.015068751161343086], [0.017582561180781744, 0.012389447135234889], [0.02052996468849165, 0.009074171371415283], [0.023139217865876142, 0.004973338822865651], [0.02534657244279087, 9.378468009673641e-05], [0.027120823883641988, -0.005086565374655761], [0.02852077609424112, -0.009966988739312265], [0.029495245624780612, -0.013702781859251749], [0.029773191924602416, -0.014570551271670621], [0.030010800273665143, -0.015099043544552266], [0.03066244820442621, -0.017076978786335018], [0.030836280350739913, -0.01865368331660707], [0.03084022343417445, -0.018974228706307904], [0.030383409828204103, -0.020164714698700684], [0.030219425441572797, -0.02045660088446371], [0.02996541541969731, -0.02069025430832213], [0.028775763239506272, -0.02130968697447384], [0.02845404240681726, -0.021396952925687742], [0.026567056646727004, -0.02142165235634059], [0.024019190728741927, -0.020972740551637017], [0.02080354955159065, -0.020071161865564905], [0.016986833908267954, -0.01880904656707676], [0.012855966142909438, -0.017223334713856564], [0.008731991982111956, -0.01542268141606672], [0.005238654349994791, -0.013607341824931916], [0.004957358198569507, -0.013450864512898007], [0.002041427277171244, -0.011597699303339997], [-0.0005382769108649943, -0.009611352754986709], [-0.002552380227375376, -0.00773665971736431], [-0.004051800654644058, -0.006051568147400357], [-0.005105566780143426, -0.004647330647967617], [-0.00575999459877288, -0.003519655014770707], [-0.005916449385959548, -0.002993952576993941], [-0.007104381992543297, -0.002970962024926233], [-0.008931543052869468, -0.0028766587133609374], [-0.008770063649980772, -0.004153224730260686], [-0.008765930752593862, -0.005422654511374215], [-0.008874123896944544, -0.0065906736983702575], [-0.009080207446933029, -0.008272933522095537], [-0.009384520804416973, -0.010025270519891424], [-0.00966812043892037, -0.011559499053426693], [-0.010083484424814644, -0.013193621372569271], [-0.010803485363183932, -0.014692208499465717], [-0.012030529985138084, -0.0160787281946416], [-0.01400649280011919, -0.017403024218324466], [-0.01680531285893815, -0.018627263846756864], [-0.017110604699004328, -0.0187403949413544], [-0.020317557341790256, -0.019752650459143387], [-0.023349005846533353, -0.02040755019488242], [-0.025648624803177717, -0.02049291363212221], [-0.026009456282247465, -0.020469861478238746], [-0.026357143971117044, -0.020343158413844615], [-0.02751412063398082, -0.019840329258952374], [-0.02781022248759546, -0.019632733822930626], [-0.028000163758448427, -0.019348554357805456], [-0.02827481366375747, -0.01838090939276285], [-0.028347443918171632, -0.017950210979679308]], 'holes': []}], 'simplify_tolerance': 1.1837533470469218e-05, 'sketch_entity_count': 93}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
